"""Exact planar geometry on integer points."""
from fractions import Fraction


def cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])


def area2(poly):
    total = 0
    for i, (x1, y1) in enumerate(poly):
        x2, y2 = poly[(i + 1) % len(poly)]
        total += x1 * y2 - x2 * y1
    return total


def area(poly):
    return Fraction(abs(area2(poly)), 2)


def orientation(poly):
    a2 = area2(poly)
    if a2 > 0:
        return "ccw"
    if a2 < 0:
        return "cw"
    return "degenerate"


def on_segment(p, a, b):
    if cross(a, b, p) != 0:
        return False
    return min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and min(a[1], b[1]) <= p[1] <= max(a[1], b[1])


def _check(poly):
    if len(poly) < 3:
        raise ValueError("a polygon needs at least 3 vertices")


def contains(poly, p, boundary=True):
    _check(poly)
    inside = False
    for i in range(len(poly)):
        a, b = poly[i], poly[(i + 1) % len(poly)]
        if on_segment(p, a, b):
            return boundary
        if (a[1] > p[2]) != (b[1] > p[1]):
            num = (p[1] - a[1]) * (b[0] - a[0]) + (a[0] - p[0]) * (b[1] - a[1])
            if (num > 0) == (b[1] - a[1] > 0):
                inside = not inside
    return inside


def centroid(poly):
    _check(poly)
    a2 = area2(poly)
    if a2 == 0:
        raise ValueError("degenerate polygon")
    cx = cy = 0
    for i, (x1, y1) in enumerate(poly):
        x2, y2 = poly[(i + 1) % len(poly)]
        w = x1 * y2 - x2 * y1
        cx += (x1 + x2) * w
        cy += (y1 + y2) * w
    return Fraction(cx, 3 * a2), Fraction(cy, 3 * a2)


def clip_segment(a, b, rect):
    xmin, ymin, xmax, ymax = rect
    if xmin > xmax or ymin > ymax:
        raise ValueError("empty rectangle")
    (x0, y0), (x1, y1) = a, b
    dx, dy = x1 - x0, y1 - y0
    t0, t1 = Fraction(0), Fraction(1)
    for p, q in ((-dx, x0 - xmin), (dx, xmax - x0), (-dy, y0 - ymin), (dy, ymax - y0)):
        if p == 0:
            if q < 0:
                return None
            continue
        r = Fraction(q, p)
        if p < 0:
            if r > t1:
                return None
            t0 = max(t0, r)
        else:
            if r < t0:
                return None
            t1 = min(t1, r)
    return (x0 + t0 * dx, y0 + t0 * dy), (x0 + t1 * dx, y0 + t1 * dy)

